1	export type Customer = { yearsWithMHPCO: number };
2	
3	export type Scenario = {
4	  customer: Customer;
5	  steps: Step[];
6	};
7	
8	export type Step =
9	  | { op: "quote"; items: Item[] }
10	  | { op: "claim"; policy: number; incident: Incident };
11	
12	export type Item = {
13	  type: string;
14	  material?: string;
15	  enchantment?: number;
16	  cursed?: boolean;
17	};
18	
19	export type Incident = {
20	  cause: string;
21	  damages: Damage[];
22	};
23	
24	export type Damage = {
25	  itemType: string;
26	  amount: number;
27	};
28	
29	export type Result = { premium: number } | { payout: number; remainingCap: number };
30	
31	const PROCESSING_FEE = 5;
32	const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
33	
34	// The catalogue of insurable item types. Each type carries both figures the
35	// office needs: what it costs to insure (base premium) and what it is worth
36	// when destroyed (insurance value). Keeping them in one row means a new item
37	// type is one edit, and the two figures can never drift apart.
38	const CATALOGUE: Record<string, { basePremium: number; insuranceValue: number }> = {
39	  sword: { basePremium: 100, insuranceValue: 1000 },
40	  amulet: { basePremium: 60, insuranceValue: 600 },
41	  staff: { basePremium: 80, insuranceValue: 800 },
42	  potion: { basePremium: 40, insuranceValue: 400 },
43	  rune: { basePremium: 25, insuranceValue: 250 },
44	  moonstone: { basePremium: 25, insuranceValue: 250 },
45	};
46	
47	// Three of this file's lookups can miss, and in every case a miss is the office
48	// declining rather than a bug: an uninsurable type, an uncovered item, an absent
49	// policy. Each caller names its own offender; this says once what they share — a
50	// miss is a domain error naming what was declined, never an undefined that
51	// travels on to surface later as a TypeError.
52	const foundOrThrow = <Found,>(found: Found | undefined, declined: string): Found => {
53	  if (found === undefined) {
54	    throw new Error(declined);
55	  }
56	  return found;
57	};
58	
59	// Both catalogue figures are read through this one row lookup, so an item's type
60	// is resolved against the catalogue in exactly one place — which makes it also
61	// the one place that can tell an insurable type from an uninsurable one. The
62	// catalogue does not merely price the types the MHPCO insures; it DEFINES them,
63	// so a missing row is not a lookup miss to defend against but the office
64	// declining the item, and it is reported in those terms.
65	const catalogueEntryFor = (item: Item) =>
66	  foundOrThrow(
67	    CATALOGUE[item.type],
68	    `the MHPCO does not insure items of type "${item.type}"`,
69	  );
70	
71	// Totalling a catalogue column over a list of items is the same operation on the
72	// premium side and the claim side; only the column differs. Naming it once keeps
73	// the two columns visibly separate — which is the point: the building-block
74	// discount rewrites the basePremium column and never touches insuranceValue.
75	const totalOfColumn =
76	  (columnOf: (item: Item) => number) =>
77	  (items: Item[]): number =>
78	    items.reduce((total, item) => total + columnOf(item), 0);
79	
80	const basePremiumOf = (item: Item): number => catalogueEntryFor(item).basePremium;
81	
82	const BLOCK_SIZE = 3;
83	const BLOCK_BASE_PREMIUM = 60;
84	
85	const formsABuildingBlock = (alikeItems: Item[]): boolean =>
86	  alikeItems.length === BLOCK_SIZE;
87	
88	const sumOfBasePremiums = totalOfColumn(basePremiumOf);
89	
90	const CURSE_SURCHARGE_RATE = 0.5;
91	const HIGH_ENCHANTMENT_LEVEL = 5;
92	const HIGH_ENCHANTMENT_SURCHARGE_RATE = 0.3;
93	
94	const isCursed = (item: Item): boolean => item.cursed === true;
95	
96	// An unenchanted item is enchantment 0, so every threshold reads the level the
97	// same way. The MHPCO sets several enchantment thresholds for different rules;
98	// each names its own level and compares through here.
99	const enchantmentLevelOf = (item: Item): number => item.enchantment ?? 0;
100	
101	const carriesEnchantmentSurcharge = (item: Item): boolean =>
102	  enchantmentLevelOf(item) >= HIGH_ENCHANTMENT_LEVEL;
103	
104	// A rate table prices one subject: every row whose risk applies contributes its
105	// rate, and the total is their sum. Both the item surcharges and the policy-wide
106	// modifiers are rate tables — they differ only in what they are applied to.
107	type RateTable<Subject> = { appliesTo: (subject: Subject) => boolean; rate: number }[];
108	
109	const totalRateFrom = <Subject,>(table: RateTable<Subject>, subject: Subject): number =>
110	  table.reduce((total, row) => (row.appliesTo(subject) ? total + row.rate : total), 0);
111	
112	// Every item-specific surcharge is a rate on THAT item's base premium, charged
113	// when its risk applies. Adding a new one means adding a row here — nothing else.
114	const ITEM_SURCHARGES: RateTable<Item> = [
115	  { appliesTo: isCursed, rate: CURSE_SURCHARGE_RATE },
116	  { appliesTo: carriesEnchantmentSurcharge, rate: HIGH_ENCHANTMENT_SURCHARGE_RATE },
117	];
118	
119	const surchargeRateOn = (item: Item): number => totalRateFrom(ITEM_SURCHARGES, item);
120	
121	const surchargeOn = (item: Item): number => basePremiumOf(item) * surchargeRateOn(item);
122	
123	// The surcharge is a third catalogue-derived column alongside basePremium and
124	// insuranceValue — a per-item amount totalled the same way, so it is totalled by
125	// the same named operation rather than by a fold spelled out again here.
126	const itemSurchargesOn = totalOfColumn(surchargeOn);
127	
128	// Items of the same type are "alike"; each group is priced together so a
129	// building block can be recognised.
130	const alikeItemGroupsIn = (items: Item[]): Item[][] => [
131	  ...items
132	    .reduce(
133	      (groups, item) => groups.set(item.type, [...(groups.get(item.type) ?? []), item]),
134	      new Map<string, Item[]>(),
135	    )
136	    .values(),
137	];
138	
139	const basePremiumOfAlikeItems = (alikeItems: Item[]): number =>
140	  formsABuildingBlock(alikeItems) ? BLOCK_BASE_PREMIUM : sumOfBasePremiums(alikeItems);
141	
142	const policyBaseOf = (items: Item[]): number =>
143	  alikeItemGroupsIn(items).reduce(
144	    (sum, alikeItems) => sum + basePremiumOfAlikeItems(alikeItems),
145	    0,
146	  );
147	
148	// Rounding always favours the MHPCO. Which direction that is follows from which
149	// way the money moves: an amount the office RECEIVES is rounded up, an amount it
150	// PAYS is rounded down. Naming the two directions makes the rule one concept
151	// rather than two opposite-looking halves, and each call site says which kind of
152	// amount it holds — so the reason for the direction is in the code, not a comment.
153	const settledAsReceived = Math.ceil;
154	const settledAsPaid = Math.floor;
155	
156	const LOYALTY_YEARS = 2;
157	const LOYALTY_DISCOUNT_RATE = -0.2;
158	
159	const FOLLOW_UP_CONTRACT_DISCOUNT_RATE = -0.15;
160	
161	// A quote insures items the policy did not previously cover, so every quote is
162	// a first insurance OF THOSE ITEMS — including a follow-up contract, which is a
163	// later contract for the same customer but still the first for its own items.
164	// That is why this holds for every quote and reads as a condition that is always
165	// met, rather than as a rule with no condition at all.
166	const insuresItemsForTheFirstTime = (): boolean => true;
167	
168	const isLongStanding = ({ customer }: QuoteContext): boolean =>
169	  customer.yearsWithMHPCO >= LOYALTY_YEARS;
170	
171	const isFollowUpContract = ({ precedingQuotes }: QuoteContext): boolean =>
172	  precedingQuotes > 0;
173	
174	// A quote is priced from the customer plus its place in the scenario's history.
175	type QuoteContext = { customer: Customer; precedingQuotes: number };
176	
177	// Every policy-wide modifier is a rate on the UNMODIFIED policy base — never on a
178	// base that already includes the item surcharges. Surcharges carry a positive
179	// rate, discounts a negative one. Adding a new one means adding a row here.
180	const POLICY_MODIFIERS: RateTable<QuoteContext> = [
181	  { appliesTo: insuresItemsForTheFirstTime, rate: FIRST_INSURANCE_SURCHARGE_RATE },
182	  { appliesTo: isLongStanding, rate: LOYALTY_DISCOUNT_RATE },
183	  { appliesTo: isFollowUpContract, rate: FOLLOW_UP_CONTRACT_DISCOUNT_RATE },
184	];
185	
186	const policyModifiersOn = (policyBase: number, context: QuoteContext): number =>
187	  policyBase * totalRateFrom(POLICY_MODIFIERS, context);
188	
189	const quoteFor = (items: Item[], context: QuoteContext): Result => {
190	  const policyBase = policyBaseOf(items);
191	  const riskAdjustedBase = policyBase + itemSurchargesOn(items);
192	  return {
193	    premium: settledAsReceived(
194	      riskAdjustedBase + policyModifiersOn(policyBase, context) + PROCESSING_FEE,
195	    ),
196	  };
197	};
198	
199	const DEDUCTIBLE_PER_DAMAGE = 100;
200	const CAP_MULTIPLE_OF_INSURANCE_SUM = 2;
201	
202	const insuranceValueOf = (item: Item): number => catalogueEntryFor(item).insuranceValue;
203	
204	// The insurance sum totals the value column over every insured item — one item,
205	// one row, no grouping. Blocks are a premium concept and cannot reach it.
206	const insuranceSumOf = totalOfColumn(insuranceValueOf);
207	
208	// A policy created by a quote step, tracked by that step's index so later claims
209	// can find it and draw down its cap.
210	type Policy = { items: Item[]; remainingCap: number };
211	
212	const policyFor = (items: Item[]): Policy => ({
213	  items,
214	  remainingCap: insuranceSumOf(items) * CAP_MULTIPLE_OF_INSURANCE_SUM,
215	});
216	
217	const HALF_REIMBURSEMENT_ENCHANTMENT_LEVEL = 8;
218	const HALF_REIMBURSEMENT_RATE = 0.5;
219	const FULL_REIMBURSEMENT_RATE = 1;
220	
221	// A distinct rule from the premium's HIGH_ENCHANTMENT_LEVEL, at a distinct
222	// level: this one halves what a claim pays out, that one raises what a policy
223	// costs. They move independently — deliberately not shared.
224	const reimbursesOnlyHalf = (item: Item): boolean =>
225	  enchantmentLevelOf(item) >= HALF_REIMBURSEMENT_ENCHANTMENT_LEVEL;
226	
227	// How much of the damage the MHPCO reimburses, before the deductible bites.
228	const reimbursementRateFor = (item: Item): number =>
229	  reimbursesOnlyHalf(item) ? HALF_REIMBURSEMENT_RATE : FULL_REIMBURSEMENT_RATE;
230	
231	// A damage names only an item TYPE, so it can identify no more than the type of
232	// the item it refers to — which is why this takes the type alone: the amount has
233	// no say in WHICH item answers for the damage. It returns the first insured item
234	// of that type as the representative whose traits price the damage.
235	//
236	// It is also the claim side's coverage guard. A type absent from the policy and
237	// a type the MHPCO does not insure at all are indistinguishable here, and both
238	// are declined by this one lookup: an uninsurable type could never have been
239	// quoted, so it can never appear among a policy's items.
240	//
241	// UNTESTED ASSUMPTION: that the first match is the right representative. Where a
242	// policy holds several alike items, the suite never distinguishes them — its only
243	// two-alike-items example insures two IDENTICAL swords, so first-match is
244	// unobservable there, and the spec offers no example pairing one type with
245	// DIFFERING enchantment or material. So this is an assumption the tests permit,
246	// not one they confirm. Should such an example appear, the damage would have to
247	// be matched to a specific item and this would be the place that changes.
248	const insuredItemOfType = (policy: Policy, itemType: string): Item =>
249	  foundOrThrow(
250	    policy.items.find((item) => item.type === itemType),
251	    `the policy does not cover an item of type "${itemType}"`,
252	  );
253	
254	// A damage is what the incident cost; an office cannot be owed money by a
255	// misfortune, so a negative amount is a malformed claim rather than a refund.
256	const damagedAmountOf = (damage: Damage): number => {
257	  if (damage.amount < 0) {
258	    throw new Error(`a damage cannot be negative, but was ${damage.amount}`);
259	  }
260	  return damage.amount;
261	};
262	
263	const reimbursedAmountFor = (damage: Damage, policy: Policy): number =>
264	  damagedAmountOf(damage) *
265	  reimbursementRateFor(insuredItemOfType(policy, damage.itemType));
266	
267	// The deductible bites once per damage, after the reimbursement rate is applied
268	// — never the other way round, which would pay out more.
269	const payoutForDamage = (damage: Damage, policy: Policy): number =>
270	  reimbursedAmountFor(damage, policy) - DEDUCTIBLE_PER_DAMAGE;
271	
272	// How many times each type appears among a list of things that name a type.
273	// Items and damages name theirs under different keys, so each caller says how
274	// its own kind is read rather than first flattening to a list of bare strings.
275	// The file's other by-type reading, alikeItemGroupsIn, collects the items
276	// themselves because the premium side prices them; here only the tally matters.
277	const countByType = <Named,>(
278	  named: Named[],
279	  typeOf: (one: Named) => string,
280	): Map<string, number> =>
281	  named.reduce((counts, one) => {
282	    const type = typeOf(one);
283	    return counts.set(type, (counts.get(type) ?? 0) + 1);
284	  }, new Map<string, number>());
285	
286	// A damage entry stands for one damaged item, so an incident cannot name more
287	// damages of a type than the policy insures of that type. Asking for the
288	// overclaimed type — rather than testing each damage in turn — puts this beside
289	// the file's other three misses: a lookup that yields nothing when all is well
290	// and names the offender when it is not.
291	const overclaimedTypeIn = (incident: Incident, policy: Policy): string | undefined => {
292	  const insuredCounts = countByType(policy.items, (item) => item.type);
293	  return [...countByType(incident.damages, (damage) => damage.itemType)]
294	    .filter(([type, damaged]) => damaged > (insuredCounts.get(type) ?? 0))
295	    .map(([type]) => type)
296	    .at(0);
297	};
298	
299	// The whole claim is rejected rather than settled in part, so the overclaim is
300	// checked before any damage is priced.
301	const rejectOverclaimedTypes = (incident: Incident, policy: Policy): void => {
302	  const overclaimed = overclaimedTypeIn(incident, policy);
303	  if (overclaimed !== undefined) {
304	    throw new Error(
305	      `the policy does not cover that many items of type "${overclaimed}"`,
306	    );
307	  }
308	};
309	
310	// One incident can damage several items; each damage is settled on its own
311	// (and so bears its own deductible), and the incident pays out their sum.
312	const payoutForIncident = (incident: Incident, policy: Policy): number => {
313	  rejectOverclaimedTypes(incident, policy);
314	  return incident.damages.reduce(
315	    (sum, damage) => sum + payoutForDamage(damage, policy),
316	    0,
317	  );
318	};
319	
320	// A payout is drawn from the policy's cap, leaving less for later claims.
321	const capDrawnDownBy = (policy: Policy, payout: number): Policy => ({
322	  ...policy,
323	  remainingCap: policy.remainingCap - payout,
324	});
325	
326	// The policy pays no more than the cap it has left, however large the damage.
327	const payoutWithinCapOf = (policy: Policy, desiredPayout: number): number =>
328	  Math.min(desiredPayout, policy.remainingCap);
329	
330	// Settling a claim pays out and draws the cap down by the same amount, so the
331	// result the customer sees is the payout plus the cap that payout left behind.
332	const claimFor = (incident: Incident, policy: Policy): [Result, Policy] => {
333	  const payout = settledAsPaid(
334	    payoutWithinCapOf(policy, payoutForIncident(incident, policy)),
335	  );
336	  const settledPolicy = capDrawnDownBy(policy, payout);
337	  return [{ payout, remainingCap: settledPolicy.remainingCap }, settledPolicy];
338	};
339	
340	// What the scenario has accumulated before the current step: the results so far,
341	// the history a quote is priced against, and the policies earlier quotes created.
342	type ScenarioState = {
343	  results: Result[];
344	  precedingQuotes: number;
345	  policies: Record<number, Policy>;
346	};
347	
348	const INITIAL_SCENARIO_STATE: ScenarioState = {
349	  results: [],
350	  precedingQuotes: 0,
351	  policies: {},
352	};
353	
354	// Every step reports exactly one result and leaves one policy at its index —
355	// the two things both step kinds always do. Recording them is named once here
356	// rather than rebuilt in each of them.
357	const withStepRecorded = (
358	  state: ScenarioState,
359	  result: Result,
360	  policyIndex: number,
361	  policy: Policy,
362	): ScenarioState => ({
363	  ...state,
364	  results: [...state.results, result],
365	  policies: { ...state.policies, [policyIndex]: policy },
366	});
367	
368	const afterQuote = (
369	  state: ScenarioState,
370	  items: Item[],
371	  customer: Customer,
372	  stepIndex: number,
373	): ScenarioState => ({
374	  ...withStepRecorded(
375	    state,
376	    quoteFor(items, { customer, precedingQuotes: state.precedingQuotes }),
377	    stepIndex,
378	    policyFor(items),
379	  ),
380	  precedingQuotes: state.precedingQuotes + 1,
381	});
382	
383	// A claim names the quote step whose policy it draws on. Only a quote creates a
384	// policy, so an index no quote reached is the claim naming a policy that does
385	// not exist.
386	const policyAt = (state: ScenarioState, policyIndex: number): Policy =>
387	  foundOrThrow(
388	    state.policies[policyIndex],
389	    `there is no policy at step ${policyIndex}`,
390	  );
391	
392	const afterClaim = (
393	  state: ScenarioState,
394	  policyIndex: number,
395	  incident: Incident,
396	): ScenarioState => {
397	  const [result, settledPolicy] = claimFor(incident, policyAt(state, policyIndex));
398	  return withStepRecorded(state, result, policyIndex, settledPolicy);
399	};
400	
401	const afterStep = (
402	  state: ScenarioState,
403	  step: Step,
404	  customer: Customer,
405	  stepIndex: number,
406	): ScenarioState =>
407	  step.op === "quote"
408	    ? afterQuote(state, step.items, customer, stepIndex)
409	    : afterClaim(state, step.policy, step.incident);
410	
411	export const runScenario = (scenario: Scenario): { results: Result[] } => {
412	  const { results } = scenario.steps.reduce(
413	    (state, step, stepIndex) => afterStep(state, step, scenario.customer, stepIndex),
414	    INITIAL_SCENARIO_STATE,
415	  );
416	  return { results };
417	};
